/**
 * Default theme — Sweet & Savory portfolio (light / dark).
 * Warm, professional palette for Pieter Soudan · IT consulting.
 */
:root {
  --radius: 0.75rem;
  --background: oklch(0.99 0.008 85);
  --foreground: oklch(0.24 0.025 55);
  --card: oklch(1 0.004 85);
  --card-foreground: oklch(0.24 0.025 55);
  --popover: oklch(1 0.004 85);
  --popover-foreground: oklch(0.24 0.025 55);
  --primary: oklch(0.52 0.11 58);
  --primary-foreground: oklch(0.99 0.008 85);
  --secondary: oklch(0.96 0.018 80);
  --secondary-foreground: oklch(0.32 0.04 55);
  --muted: oklch(0.965 0.012 85);
  --muted-foreground: oklch(0.48 0.03 55);
  --accent: oklch(0.94 0.035 72);
  --accent-foreground: oklch(0.32 0.04 55);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.91 0.018 85);
  --input: oklch(0.91 0.018 85);
  --ring: oklch(0.52 0.11 58);
}

.dark {
  --background: oklch(0.17 0.018 55);
  --foreground: oklch(0.96 0.01 85);
  --card: oklch(0.21 0.02 55);
  --card-foreground: oklch(0.96 0.01 85);
  --popover: oklch(0.21 0.02 55);
  --popover-foreground: oklch(0.96 0.01 85);
  --primary: oklch(0.72 0.11 68);
  --primary-foreground: oklch(0.2 0.025 55);
  --secondary: oklch(0.27 0.022 55);
  --secondary-foreground: oklch(0.96 0.01 85);
  --muted: oklch(0.27 0.022 55);
  --muted-foreground: oklch(0.7 0.025 75);
  --accent: oklch(0.3 0.035 58);
  --accent-foreground: oklch(0.96 0.01 85);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 12%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.72 0.11 68);
}

@import "@pietersoudan/ui/globals.css";

@source "./**/*.{ts,tsx}";

html,
body,
#app {
  min-height: 100%;
}

body {
  margin: 0;
  font-feature-settings: "kern" 1, "liga" 1;
}

import path from 'node:path'
import { fileURLToPath } from 'node:url'

import { defineConfig } from 'vite'
import { devtools } from '@tanstack/devtools-vite'
import { tanstackStart } from '@tanstack/react-start/plugin/vite'
import viteReact from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

const rootDir = path.dirname(fileURLToPath(import.meta.url))
const uiSrc = path.resolve(rootDir, '../../packages/ui/src')

const config = defineConfig({
  resolve: {
    tsconfigPaths: true,
    alias: {
      '@': uiSrc,
    },
  },
  plugins: [devtools(), tailwindcss(), tanstackStart(), viteReact()],
})

export default config

import { createFileRoute } from '@tanstack/react-router'

import { LandingPage } from '#/components/landing-page'

export const Route = createFileRoute('/')({ component: Home })

function Home() {
  return <LandingPage />
}

import { HeadContent, Scripts, createRootRoute } from '@tanstack/react-router'
import { TanStackRouterDevtoolsPanel } from '@tanstack/react-router-devtools'
import { TanStackDevtools } from '@tanstack/react-devtools'

import appCss from '../styles.css?url'

export const Route = createRootRoute({
  head: () => ({
    meta: [
      { charSet: 'utf-8' },
      {
        name: 'viewport',
        content: 'width=device-width, initial-scale=1',
      },
      {
        title: 'Sweet & Savory · Pieter Soudan',
      },
      {
        name: 'description',
        content:
          'Independent IT consultant specializing in software engineering, system architecture, and full-stack web development.',
      },
    ],
    links: [{ rel: 'stylesheet', href: appCss }],
  }),
  shellComponent: RootDocument,
})

function RootDocument({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" data-theme="default" className="light" suppressHydrationWarning>
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <TanStackDevtools
          config={{ position: 'bottom-right' }}
          plugins={[
            {
              name: 'Tanstack Router',
              render: <TanStackRouterDevtoolsPanel />,
            },
          ]}
        />
        <Scripts />
      </body>
    </html>
  )
}
